initJs:
function(container, apiUrl, tables) {
  // 店舗データの初期化
  const storeSelect = container.querySelector("#store-select");
  const storeTable = tables.find(t => t.tableName === "店舗マスタ");
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 需要予測結果テーブルの再描画関数
  function renderPredictionRows(rows) {
    const tbody = container.querySelector("#prediction-list");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.予測結果ID || r.id}">
        <td>${r.商品コード || "-"}</td>
        <td>${r.商品名 || "-"}</td>
        <td>${r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : "-"}</td>
        <td>${r.予測数量 || 0}</td>
        <td>${r.予測精度 || 0}%</td>
        <td>${r.推奨発注数量 || 0}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${r.予測ステータス === '完了' ? '#28a745' : r.予測ステータス === 'エラー' ? '#dc3545' : '#ffc107'}; 
                       color: white;">
            ${r.予測ステータス || "未実行"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.予測結果ID || r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.予測結果ID || r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  const predictionTableIndex = tables.findIndex(t => t.tableName === "需要予測結果");
  if (predictionTableIndex >= 0) {
    renderPredictionRows(tables[predictionTableIndex].records || []);
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // 処理中表示関数
  function showProcessing(show) {
    const processingDiv = container.querySelector("#processing-message");
    if (show) {
      processingDiv.classList.remove("hidden");
    } else {
      processingDiv.classList.add("hidden");
    }
  }

  // 予測結果表示関数
  function showPredictionResults() {
    const resultsDiv = container.querySelector("#prediction-results");
    resultsDiv.classList.remove("hidden");

    // サンプルデータで予測精度指標を更新
    container.querySelector("#accuracy-score").textContent = "87.5%";
    container.querySelector("#confidence-level").textContent = "92.3%";
    container.querySelector("#model-version").textContent = "v2.1.0";

    // 影響要因分析結果を更新
    container.querySelector("#seasonal-impact").textContent = "中程度 (+15%)";
    container.querySelector("#weather-impact").textContent = "高 (+25%)";
    container.querySelector("#event-impact").textContent = "低 (+3%)";

    // 天候・イベント情報を更新
    container.querySelector("#weather-forecast").textContent = "晴れ時々曇り";
    container.querySelector("#scheduled-events").textContent = "地域祭り (3日後)";

    // グラフを描画
    drawPredictionChart();
    drawComparisonChart();
  }

  // 予測グラフ描画関数
  function drawPredictionChart() {
    const canvas = container.querySelector("#prediction-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // グラフエリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 背景クリア
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const days = 7;
    const actualData = [120, 135, 98, 156, 142, 189, 167];
    const predictedData = [125, 140, 95, 160, 145, 185, 170];

    // Y軸の最大値
    const maxValue = Math.max(...actualData, ...predictedData) * 1.2;

    // グリッド線描画
    ctx.strokeStyle = '#3a4a6a';
    ctx.lineWidth = 1;

    // 横線
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();
    }

    // 縦線
    for (let i = 0; i <= days - 1; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      ctx.beginPath();
      ctx.moveTo(x, padding);
      ctx.lineTo(x, padding + chartHeight);
      ctx.stroke();
    }

    // 実績データ線
    ctx.strokeStyle = '#28a745';
    ctx.lineWidth = 3;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const y = padding + chartHeight - (actualData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測データ線
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 3;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const y = padding + chartHeight - (predictedData[i] / maxValue) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    // X軸ラベル
    for (let i = 0; i < days; i++) {
      const x = padding + (chartWidth / (days - 1)) * i;
      const date = new Date();
      date.setDate(date.getDate() + i);
      ctx.fillText(date.toLocaleDateString('ja-JP', { month: 'numeric', day: 'numeric' }), x, canvas.height - 20);
    }

    // Y軸ラベル
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      const value = Math.round(maxValue * (1 - i / 5));
      ctx.fillText(value.toString(), padding - 10, y + 4);
    }

    // 凡例
    ctx.textAlign = 'left';
    ctx.fillStyle = '#28a745';
    ctx.fillRect(padding, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績', padding + 30, 30);

    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 100, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測', padding + 130, 30);
  }

  // 比較グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // 背景クリア
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプル比較データ（棒グラフ）
    const categories = ['食品', '飲料', '日用品', '冷凍食品'];
    const actualValues = [85, 92, 78, 88];
    const predictedValues = [87, 89, 82, 85];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / (categories.length * 3);

    // 最大値
    const maxValue = 100;

    // 棒グラフ描画
    categories.forEach((category, i) => {
      const x = padding + i * (chartWidth / categories.length);

      // 実績棒
      const actualHeight = (actualValues[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#28a745';
      ctx.fillRect(x + barWidth * 0.2, padding + chartHeight - actualHeight, barWidth * 0.8, actualHeight);

      // 予測棒
      const predictedHeight = (predictedValues[i] / maxValue) * chartHeight;
      ctx.fillStyle = '#007bff';
      ctx.fillRect(x + barWidth * 1.2, padding + chartHeight - predictedHeight, barWidth * 0.8, predictedHeight);

      // カテゴリラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, x + barWidth, canvas.height - 20);
    });
  }

  // バリデーション関数
  function validatePredictionForm() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!startDate) {
      showError("予測期間の開始日を設定してください");
      return false;
    }

    if (!endDate) {
      showError("予測期間の終了日を設定してください");
      return false;
    }

    if (new Date(startDate) >= new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (new Date(startDate) < new Date()) {
      showError("開始日は現在日以降の日付を設定してください");
      return false;
    }

    const seasonal = container.querySelector("#seasonal-model").checked;
    const event = container.querySelector("#event-model").checked;
    const weather = container.querySelector("#weather-model").checked;

    if (!seasonal && !event && !weather) {
      showError("予測モデルを選択してください");
      return false;
    }

    return true;
  }

  // AI予測実行ボタン
  container.querySelector("#btn-predict").addEventListener("click", async () => {
    if (!validatePredictionForm()) return;

    showProcessing(true);

    // 予測処理のシミュレーション
    setTimeout(async () => {
      showProcessing(false);

      const storeId = container.querySelector("#store-select").value;
      const category = container.querySelector("#category-select").value;
      const startDate = container.querySelector("#start-date").value;
      const endDate = container.querySelector("#end-date").value;

      // 需要予測結果を保存
      const predictionData = {
        店舗ID: storeId,
        商品ID: "sample-product-id",
        予測対象日: startDate,
        予測数量: Math.floor(Math.random() * 200) + 50,
        予測精度: Math.floor(Math.random() * 30) + 70,
        推奨発注数量: Math.floor(Math.random() * 150) + 30,
        予測モデルバージョン: "v2.1.0",
        予測ステータス: "完了",
        発注済フラグ: false,
        備考: `カテゴリ: ${category}`,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      if (predictionTableIndex >= 0) {
        const saved = await window.aivicApi.save(predictionTableIndex, predictionData);
        if (saved) {
          const rows = await window.aivicApi.list(predictionTableIndex);
          if (rows) renderPredictionRows(rows);
        }
      }

      showPredictionResults();
    }, 2000);
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    if (predictionTableIndex >= 0) {
      const rows = await window.aivicApi.list(predictionTableIndex);
      if (rows) {
        const headers = ["商品コード", "商品名", "予測対象日", "予測数量", "予測精度", "推奨発注数量", "予測ステータス"];
        const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
          rows.map(r => [
            r.商品コード || "",
            r.商品名 || "",
            r.予測対象日 || "",
            r.予測数量 || "",
            r.予測精度 || "",
            r.推奨発注数量 || "",
            r.予測ステータス || ""
          ].join(",")).join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "demand_prediction_results.csv";
        link.click();
      }
    }
  });

  // 行レベル操作（削除・詳細）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この予測結果を削除しますか？")) return;

      if (predictionTableIndex >= 0) {
        await window.aivicApi.delete(predictionTableIndex, deleteBtn.dataset.id);
        const rows = await window.aivicApi.list(predictionTableIndex);
        if (rows) renderPredictionRows(rows);
      }
    }

    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778591885672"); // AI需要予測処理画面
    }
  });

  // 初期データ読み込み
  if (predictionTableIndex >= 0) {
    window.aivicApi.list(predictionTableIndex).then(rows => {
      if (rows) renderPredictionRows(rows);
    });
  }
}
